import{_ as t,H as a,f as i,i as s}from"./chunks/framework.BH2BK_3i.js";const p=JSON.parse('{"title":"好诗相伴05｜见自己：我在诗中渡自己","description":"","frontmatter":{},"headers":[],"relativePath":"如何读懂一首诗/好诗相伴05｜见自己：我在诗中渡自己.md","filePath":"如何读懂一首诗/好诗相伴05｜见自己：我在诗中渡自己.md","lastUpdated":1779819710000}'),n={name:"如何读懂一首诗/好诗相伴05｜见自己：我在诗中渡自己.md"};function r(o,e,E,b,g,c){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="好诗相伴05-见自己-我在诗中渡自己" tabindex="-1">好诗相伴05｜见自己：我在诗中渡自己 <a class="header-anchor" href="#好诗相伴05-见自己-我在诗中渡自己" aria-label="Permalink to &quot;好诗相伴05｜见自己：我在诗中渡自己&quot;">​</a></h1><p>好诗相伴，千金不换，你好，我是天博。</p><p>今天我们的“好诗相伴”栏目，我想给你读的是“见自己”这个话题下的诗。我在“见自己”这个话题里把重点放在“诗词给了我们什么”上，也就是怎样从诗词里汲取对我们有帮助的精神力量。我讲了苏轼的乐观豁达、王维的返璞归真和秋瑾的自强不息这三种人生态度。</p><p>讲苏轼的 <a href="https://time.geekbang.org/column/article/401731" target="_blank" rel="noreferrer">乐观豁达</a> 的时候，我们主要讲了苏轼的代表作之一《定风波·莫听穿林打叶声》，在讲苏轼经历的时候，还顺带提到了他总结自己一生的《自题金山画像》，最后在煮酒论诗里分享了他被从海南赦免的时候写的《六月二十日夜渡海》</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417806/1461bbd07c1a9d8a80b023e409d719af.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417806/1461bbd07c1a9d8a80b023e409d719af.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417806/166aba8ba06e09819f44ab5bcffb7e2a.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417806/166aba8ba06e09819f44ab5bcffb7e2a.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417806/94176c21498bb22913369fa82ecba91e.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417806/94176c21498bb22913369fa82ecba91e.jpg" alt=""></a></p><p>而在讲王维的 <a href="https://time.geekbang.org/column/article/402924" target="_blank" rel="noreferrer">返璞归真</a> 的时候，我们主要讲的是他的《酌酒与裴迪》，还有提到了和王维这首诗有共同点的《行行重行行》，所以我在煮酒论诗里给你分享了这首诗。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417806/c7a02a37cb032e8e1255c5df94603f23.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417806/c7a02a37cb032e8e1255c5df94603f23.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417806/b4af665f0f8d068c7af754821195dd68.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417806/b4af665f0f8d068c7af754821195dd68.jpg" alt=""></a></p><p>在最后一讲，讲 <a href="https://time.geekbang.org/column/article/404095" target="_blank" rel="noreferrer">自强不息</a> 的时候，我用来压轴的是秋瑾的《红毛刀歌》。因为这一讲我提到了伟人毛泽东，所以我在煮酒论诗里和你分享了他的《水调歌头·重上井冈山》。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417806/b35b5168e3a7182f3919c3eacc88875b.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417806/b35b5168e3a7182f3919c3eacc88875b.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417806/b16d90d45ce06af7a437c754b39d8e0a.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417806/b16d90d45ce06af7a437c754b39d8e0a.jpg" alt=""></a></p><p>到这里，我们的好诗相伴就结束了。这是我们好诗相伴的最后一讲了。如果这里面有你喜欢的诗，欢迎你多听两遍。愿你的人生好诗相伴，千金不换，我们有缘再见。</p>',14)])])}const l=t(n,[["render",r]]);export{p as __pageData,l as default};
